import { createClient, SupabaseClient } from '@supabase/supabase-js';
import dotenv from 'dotenv';
import type { MonitoredSite, MonitorCheck, Incident, AlertChannel } from '@pingwatch/shared';

dotenv.config();

const SUPABASE_URL = process.env.SUPABASE_URL || '';
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY || '';

export const isRealSupabaseConfigured = (): boolean => {
  return (
    !!SUPABASE_URL &&
    !!SUPABASE_SERVICE_KEY &&
    !SUPABASE_URL.includes('placeholder') &&
    !SUPABASE_URL.includes('your-project') &&
    SUPABASE_URL.startsWith('http')
  );
};

let supabaseInstance: SupabaseClient | null = null;

export const getSupabaseClient = (): SupabaseClient => {
  if (!supabaseInstance) {
    if (isRealSupabaseConfigured()) {
      supabaseInstance = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
        auth: { persistSession: false, autoRefreshToken: false },
      });
    } else {
      supabaseInstance = createClient('https://demo.supabase.co', 'dummy-key', {
        auth: { persistSession: false },
      });
    }
  }
  return supabaseInstance;
};
